 add('SecurityHeaders','AWS::CloudFront::ResponseHeadersPolicy',{'ResponseHeadersPolicyConfig':{'Name':'wizz-production-admin-web-security','SecurityHeadersConfig':{'ContentTypeOptions':{'Override':True},'FrameOptions':{'FrameOption':'DENY','Override':True},'ReferrerPolicy':{'ReferrerPolicy':'no-referrer','Override':True},'StrictTransportSecurity':{'AccessControlMaxAgeSec':31536000,'Override':True},'ContentSecurityPolicy':{'ContentSecurityPolicy':csp,'Override':True}},'CustomHeadersConfig':{'Items':[{'Header':'Cache-Control','Value':'no-store','Override':True}]}}})
 common={'ViewerProtocolPolicy':'redirect-to-https','CachePolicyId':{'Ref':'NoCache'},'ResponseHeadersPolicyId':{'Ref':'SecurityHeaders'}}
 add('Distribution','AWS::CloudFront::Distribution',{'DistributionConfig':{'Enabled':True,'Comment':'Wizz production administration bootstrap','DefaultRootObject':'index.html','HttpVersion':'http2','PriceClass':'PriceClass_100','Origins':[{'Id':'web','DomainName':{'Fn::GetAtt':['WebBucket','RegionalDomainName']},'OriginAccessControlId':{'Ref':'OriginAccess'},'S3OriginConfig':{'OriginAccessIdentity':''}},{'Id':'session','DomainName':'y6vmu5snh3.execute-api.us-east-1.amazonaws.com','OriginPath':'/production','CustomOriginConfig':{'HTTPSPort':443,'OriginProtocolPolicy':'https-only','OriginSSLProtocols':['TLSv1.2']}}],'DefaultCacheBehavior':{**common,'TargetOriginId':'web','AllowedMethods':['GET','HEAD','OPTIONS']},'CacheBehaviors':[{**common,'PathPattern':'/staff/*','TargetOriginId':'session','AllowedMethods':['GET','HEAD','OPTIONS','PUT','PATCH','POST','DELETE'],'OriginRequestPolicyId':{'Ref':'ApiRequestPolicy'}}],'CustomErrorResponses':[{'ErrorCode':c,'ErrorCachingMinTTL':0} for c in [403,404,500,502,503,504]],'ViewerCertificate':{'CloudFrontDefaultCertificate':True}}})
