 t['Outputs']={'WebsiteUrl':{'Value':sub('https://${Distribution.DomainName}')},'WebBucketName':{'Value':{'Ref':'WebBucket'}},'DistributionId':{'Value':{'Ref':'Distribution'}}};return t
